import { useState, useEffect } from 'react';
import { Area, AreaChart, ResponsiveContainer, Tooltip, XAxis, YAxis, Legend, ReferenceLine } from 'recharts';
import { useTheme } from '../../contexts/ThemeContext';

const COLORS = [
  '#f59e0b', '#06b6d4', '#8b5cf6', '#10b981', '#f43f5e', '#3b82f6',
  '#ec4899', '#84cc16', '#14b8a6', '#f97316', '#6366f1', '#a855f7'
];

export default function PriceChangeChart({ sectors = [] }) {
  const { isDark } = useTheme();
  const [chartData, setChartData] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (sectors.length === 0) {
      setLoading(false);
      return;
    }

    const fetchAllSectors = async () => {
      setLoading(true);
      try {
        // Fetch 30 days of price change data for all sectors
        const promises = sectors.map(async (sector) => {
          const res = await fetch(`/sector/kline?name=${encodeURIComponent(sector.name)}&days=30`);
          const json = await res.json();
          return { name: sector.name, change: sector.change, data: json.kline || [] };
        });

        const results = await Promise.all(promises);

        // Merge data by date
        const dateMap = {};
        results.forEach(({ name, change, data }) => {
          data.forEach(item => {
            if (!dateMap[item.date]) {
              dateMap[item.date] = { date: item.date };
            }
            dateMap[item.date][name] = item.change;  // Use change percentage
          });
        });

        // Add today's data point with current change
        const today = new Date().toISOString().slice(0, 10);
        const latestDate = Object.keys(dateMap).sort().pop();

        if (latestDate && latestDate !== today) {
          results.forEach(({ name, change, data }) => {
            if (data.length > 0 && change !== undefined) {
              if (!dateMap[today]) {
                dateMap[today] = { date: today };
              }
              dateMap[today][name] = change;
            }
          });
        }

        // Sort by date
        let merged = Object.values(dateMap).sort((a, b) => a.date.localeCompare(b.date));

        // Always add "今日" as the last label
        const placeholder = { date: '今日' };
        sectors.forEach(s => { placeholder[s.name] = merged[merged.length - 1]?.[s.name]; });
        merged.push(placeholder);

        setChartData(merged);
      } catch (e) {
        console.error('Failed to fetch sector data:', e);
      } finally {
        setLoading(false);
      }
    };

    fetchAllSectors();
  }, [sectors]);

  if (loading) {
    return (
      <div className="h-64 flex items-center justify-center">
        <div className="w-6 h-6 border-2 border-cyan-400 border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  if (chartData.length === 0) {
    return (
      <div className="h-64 flex items-center justify-center text-[var(--text-secondary)]">
        暂无板块数据
      </div>
    );
  }

  const todayLabel = '今日';

  return (
    <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-surface)] p-4">
      <div className="flex items-center gap-2 mb-3">
        <span className="text-sm font-bold text-[var(--text-primary)]">板块涨跌幅</span>
        <span className="text-xs text-[var(--text-secondary)]">近30日 + 今日实时（单位：%）</span>
      </div>

      <div className="h-72">
        <ResponsiveContainer width="100%" height="100%">
          <AreaChart data={chartData}>
            <defs>
              {sectors.map((sector, idx) => (
                <linearGradient key={sector.name} id={`g-p-${idx}`} x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor={COLORS[idx % COLORS.length]} stopOpacity={0.3} />
                  <stop offset="95%" stopColor={COLORS[idx % COLORS.length]} stopOpacity={0.02} />
                </linearGradient>
              ))}
            </defs>
            <XAxis
              dataKey="date"
              tick={{ fill: 'var(--chart-axis)', fontSize: 10 }}
              tickLine={{ stroke: 'var(--chart-grid)' }}
              axisLine={{ stroke: 'var(--chart-grid)' }}
              tickFormatter={(v) => v.slice(5)}
            />
            <YAxis
              tick={{ fill: 'var(--chart-axis)', fontSize: 10 }}
              tickLine={{ stroke: 'var(--chart-grid)' }}
              axisLine={{ stroke: 'var(--chart-grid)' }}
              tickFormatter={(v) => v ? v.toFixed(1) : ''}
              width={50}
            />
            <Tooltip
              contentStyle={{
                background: 'var(--chart-tooltip-bg)',
                border: '1px solid var(--chart-tooltip-border)',
                borderRadius: 8,
                color: 'var(--chart-tooltip-text)',
              }}
              labelStyle={{ color: 'var(--chart-tooltip-label)' }}
            />
            <Legend
              wrapperStyle={{ paddingTop: 10 }}
              formatter={(value) => <span className="text-xs text-[var(--text-secondary)]">{value}</span>}
            />
            {sectors.slice(0, 12).map((sector, idx) => (
              <Area
                key={sector.name}
                type="monotone"
                dataKey={sector.name}
                stroke={COLORS[idx % COLORS.length]}
                strokeWidth={1.5}
                fill={`url(#g-p-${idx})`}
                dot={false}
                connectNulls={false}
              />
            ))}
            {chartData.some(d => d.date === todayLabel) && (
              <ReferenceLine
                x={todayLabel}
                stroke="#22d3ee"
                strokeDasharray="3 3"
                label={{ value: ' 今日 ', fill: '#22d3ee', fontSize: 11, position: 'insideTop', offset: 10 }}
              />
            )}
          </AreaChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}
