// 用户关注的原始板块列表
const WATCH_SECTORS = [
  '证券', '有色金属', '黄金概念',
  '白酒', '煤炭', '机器人', '游戏', '电力', '创新药', '电池',
  'AI应用', '半导体设备', '锂矿', '化工', '消费电子', 'PCB', '电网',
  '光伏', '通信', '储能', '军工', 'CPO', '光纤', '商业航天', '液冷',
  '存储芯片', '半导体', '国产芯片', '稀土永磁', '油气服务', '铜缆高速',
  '算力', '新能源车', '人工智能', '通信技术', '华为概念'
];
const WATCH_SECTOR_SET = new Set(WATCH_SECTORS);
const WATCH_CANONICAL_SET = new Set(WATCH_SECTORS.map((name) => SECTOR_ALIAS[name] || name));

function isWatchedSector(name) {
  if (!name) return false;
  if (WATCH_SECTOR_SET.has(name)) return true;

  const canonical = SECTOR_ALIAS[name] || name;
  if (WATCH_CANONICAL_SET.has(canonical)) return true;

  return WATCH_SECTORS.some((watch) => name.includes(watch) || watch.includes(name));
}

export default function AllSectorsPanel() {
  const [moneyflowSectors, setMoneyflowSectors] = useState([]);
  const [priceSectors, setPriceSectors] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchSectors = async () => {
      setLoading(true);
      try {
        // 获取主力资金数据
        const resMoneyflow = await fetch('/sectors/moneyflow');
        const dataMoneyflow = await resMoneyflow.json();

        const moneyflowFiltered = (dataMoneyflow.sectors || []).filter((sector) => isWatchedSector(sector.name));
        setMoneyflowSectors(moneyflowFiltered);

        // 获取板块涨跌数据
        const resPrice = await fetch('/sectors');
        const dataPrice = await resPrice.json();

        const priceFiltered = (dataPrice.sectors || []).filter((sector) => isWatchedSector(sector.name));
        setPriceSectors(priceFiltered);
      } catch (e) {
        console.error('Failed to fetch sectors:', e);
      } finally {
        setLoading(false);
      }
    };
    fetchSectors();

    // 每10分钟刷新一次
    const interval = setInterval(fetchSectors, 10 * 60 * 1000);
    return () => clearInterval(interval);
  }, []);

  if (loading) {
    return (
      <div className="h-32 flex items-center justify-center">
        <div className="w-6 h-6 border-2 border-cyan-400 border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* 主力资金流向图 */}
      <SectorTrendChart sectors={moneyflowSectors} />

      {/* 板块涨跌幅图 */}
      <PriceChangeChart sectors={priceSectors} />
    </div>
  );
}
